create table RB_PCP_LIMIT_CUMULATIVE (INTERNAL_KEY INT not null  ,LIMIT_TYPE VARCHAR(2) not null  ,AGREEMENT_ID VARCHAR(50) not null  ,CLIENT_NO VARCHAR(22) not null  ,LIMIT_NUM INT null  ,LIMIT_AMT DECIMAL(17,2) null  ,CR_DR_IND VARCHAR(3) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(INTERNAL_KEY,LIMIT_TYPE,AGREEMENT_ID,CLIENT_NO));